package main

import (
	"context"
	"fmt"
	"net/http"
	"net/http/httputil"
	"net/url"
	"sync"
	"time"
)

// ResourceHandle represents a managed resource with reference counting
type ResourceHandle struct {
	ID       string
	Data     []byte
	refCount int
	freed    bool
	mu       sync.Mutex
}

func (r *ResourceHandle) Acquire() {
	r.mu.Lock()
	r.refCount++
	r.mu.Unlock()
}

func (r *ResourceHandle) Release() bool {
	r.mu.Lock()
	r.refCount--
	current := r.refCount
	alreadyFreed := r.freed
	r.mu.Unlock()

	if current <= 0 && !alreadyFreed {
		r.Free()
		return true
	}
	return false
}

func (r *ResourceHandle) Free() {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.freed {
		return // idempotent - no double-free
	}
	r.freed = true
	r.Data = nil
}

// JobQueue manages background work items
type JobQueue struct {
	jobs     map[string]*ResourceHandle
	mu       sync.RWMutex
	workerCh chan string
}

func NewJobQueue() *JobQueue {
	jq := &JobQueue{
		jobs:     make(map[string]*ResourceHandle),
		workerCh: make(chan string, 100),
	}
	go jq.processWorker()
	return jq
}

func (jq *JobQueue) Submit(id string, data []byte) {
	handle := &ResourceHandle{ID: id, Data: data, refCount: 0}
	handle.Acquire() // ref for the map

	jq.mu.Lock()
	jq.jobs[id] = handle
	jq.mu.Unlock()

	jq.workerCh <- id
}

func (jq *JobQueue) Cancel(id string) bool {
	jq.mu.Lock()
	handle, exists := jq.jobs[id]
	if exists {
		delete(jq.jobs, id)
	}
	jq.mu.Unlock()

	if exists {
		handle.Release() // release map reference
		return true
	}
	return false
}

func (jq *JobQueue) processWorker() {
	for id := range jq.workerCh {
		jq.mu.Lock()
		handle, exists := jq.jobs[id]
		if exists {
			delete(jq.jobs, id)
		}
		jq.mu.Unlock()

		if !exists {
			// Job was cancelled and already cleaned up
			continue
		}

		// Simulate processing
		jq.processJob(handle)

		// After processing, release our reference
		handle.Release()
	}
}

func (jq *JobQueue) processJob(handle *ResourceHandle) {
	// Simulate work that takes time
	time.Sleep(50 * time.Millisecond)
	fmt.Printf("Processed job %s\n", handle.ID)
}

// HTTP handlers
var queue = NewJobQueue()

func submitHandler(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	if id == "" {
		http.Error(w, "missing id", http.StatusBadRequest)
		return
	}
	queue.Submit(id, []byte("payload-"+id))
	w.WriteHeader(http.StatusAccepted)
	fmt.Fprintf(w, "Job %s submitted\n", id)
}

func cancelHandler(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	if id == "" {
		http.Error(w, "missing id", http.StatusBadRequest)
		return
	}
	if queue.Cancel(id) {
		fmt.Fprintf(w, "Job %s cancelled\n", id)
	} else {
		http.Error(w, "job not found", http.StatusNotFound)
	}
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	fmt.Fprint(w, "ok")
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/submit", submitHandler)
	mux.HandleFunc("/cancel", cancelHandler)
	mux.HandleFunc("/health", healthHandler)

	// Backend server
	go func() {
		server := &http.Server{
			Addr:         ":8081",
			Handler:      mux,
			ReadTimeout:  10 * time.Second,
			WriteTimeout: 10 * time.Second,
		}
		server.ListenAndServe()
	}()

	time.Sleep(100 * time.Millisecond)

	// Reverse proxy (no retry - idempotent design handles duplicates)
	backendURL, _ := url.Parse("http://localhost:8081")
	proxy := httputil.NewSingleHostReverseProxy(backendURL)

	proxy.Transport = &safeTransport{
		base: http.DefaultTransport,
	}

	proxyServer := &http.Server{
		Addr:         ":8080",
		Handler:      proxy,
		ReadTimeout:  5 * time.Second,
		WriteTimeout: 5 * time.Second,
	}

	fmt.Println("Reverse proxy listening on :8080")
	proxyServer.ListenAndServe()
}

type safeTransport struct {
	base http.RoundTripper
}

func (t *safeTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	ctx := req.Context()
	if ctx.Err() != nil {
		return nil, ctx.Err()
	}
	reqCopy := req.Clone(context.Background())
	return t.base.RoundTrip(reqCopy)
}
